"""
    Given a key and a list, find possible matches
    Right now it just checks for case
    """
def find_possible(key: Any, possible: Any) -> object {
    if (key in possible) {
        return key;
    }
    possible = [
        x
        for x in possible
        if (x.lower() == key)
    ];
    if (possible == []) {
        return None;
    }
    return possible[0];
}

""" xor 2 bytearray

        Args:
            b1 -- bytearray
            b2 -- bytearray

        return a bytearray
    """
def bytearray_xor(b1: Any, b2: Any) -> object {
    result = bytearray();
    for (x, y) in zip(b1, b2) {
        result.append((x ^ y));
    }
    return result;
}

"""
    Private function for obtaining min and max indicies.
    """
def _get_min_and_index(lst: Any) -> object {
    (minval, minidx) = (lst[0], 0);
    for (i, v) in enumerate(lst[1:]) {
        if (v < minval) {
            (minval, minidx) = (v, (i + 1));
        }
    }
    return (minval, minidx);
}

